WITH base AS (SELECT id, account_id, txn_type, txn_time, is_flagged, LENGTH(txn_type) txn_type_length, DAYOFWEEK(txn_time) txn_time_dayofweek, COALESCE(merchant, 'OTHER') merchant_clean FROM transactions WHERE merchant IS NOT NULL) SELECT id, account_id, txn_type, txn_time, is_flagged, txn_type_length, txn_time_dayofweek, merchant_clean, LAG(txn_type_length, 2) OVER (PARTITION BY account_id ORDER BY txn_time_dayofweek, id) prev_txn_type_length, AVG(txn_type_length) OVER (PARTITION BY account_id, txn_type ORDER BY txn_time_dayofweek, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) txn_type_length_avg_2_prior FROM base
